CREATE TABLE VENDOR (
    ID INT PRIMARY KEY,
    NAME VARCHAR(255) NOT NULL,
    ACCOUNT_ID INT NOT NULL,
    CREATED DATETIME NOT NULL,
    USER_CREATED INT NOT NULL,
    UPDATED DATETIME NULL,
    USER_UPDATED INT NULL
);

CREATE TABLE PRODUCT (
    ID INT PRIMARY KEY,
    NAME VARCHAR(255) NOT NULL,
    VENDOR_ID INT NOT NULL,
    CREATED DATETIME NOT NULL,
    STATUS INT NOT NULL,
    USER_CREATED INT NOT NULL,
    UPDATED DATETIME NULL,
    USER_UPDATED INT NULL
);

